/**
 * Register all token type schemas on the provided Config instance
 * @param {import('@tokens-studio/tokenscript-interpreter').Config} config - The config instance to register schemas on
 * @returns {import('@tokens-studio/tokenscript-interpreter').Config} The same config instance (for chaining)
 */
export function registerSchemas(config) {
  return config.registerSchemas(SCHEMAS);
}
